// Simple Asteroid Dodge game
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // Ship
  const ship = { x: width / 2, y: height - 40, w: 30, h: 30, speed: 5 };

  // Input
  const keys = { ArrowLeft: false, ArrowRight: false };
  window.addEventListener('keydown', e => { if (e.key in keys) keys[e.key] = true; });
  window.addEventListener('keyup', e => { if (e.key in keys) keys[e.key] = false; });

  // Game state
  let asteroids = [];
  let fuels = [];
  let fuel = 100; // percent
  let score = 0;
  let gameOver = false;
  let frame = 0;

  const spawnAsteroid = () => {
    const size = Math.random() * 30 + 20;
    asteroids.push({ x: Math.random() * (width - size), y: -size, w: size, h: size, speed: 2 + Math.random() * 2 });
  };
  const spawnFuel = () => {
    const size = 20;
    fuels.push({ x: Math.random() * (width - size), y: -size, w: size, h: size, speed: 2 });
  };

  const rectIntersect = (a, b) => a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

  const update = () => {
    if (gameOver) return;
    // Move ship
    if (keys.ArrowLeft) ship.x = Math.max(0, ship.x - ship.speed);
    if (keys.ArrowRight) ship.x = Math.min(width - ship.w, ship.x + ship.speed);

    // Spawn
    if (frame % 90 === 0) spawnAsteroid();
    if (frame % 600 === 0) spawnFuel();

    // Update asteroids
    asteroids.forEach(a => a.y += a.speed);
    asteroids = asteroids.filter(a => a.y < height);

    // Update fuels
    fuels.forEach(f => f.y += f.speed);
    fuels = fuels.filter(f => f.y < height);

    // Collision detection
    for (let i = 0; i < asteroids.length; i++) {
      const a = asteroids[i];
      if (rectIntersect(ship, a)) { gameOver = true; break; }
      // Score when passed bottom
      if (a.y > height) { score++; asteroids.splice(i, 1); i--; }
    }
    for (let i = 0; i < fuels.length; i++) {
      const f = fuels[i];
      if (rectIntersect(ship, f)) { fuel = Math.min(100, fuel + 30); fuels.splice(i, 1); i--; }
    }

    // Fuel drain
    fuel -= 0.05;
    if (fuel <= 0) gameOver = true;

    frame++;
  };

  const draw = () => {
    ctx.clearRect(0, 0, width, height);
    // Ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y);
    ctx.lineTo(ship.x + ship.w, ship.y);
    ctx.lineTo(ship.x + ship.w / 2, ship.y - ship.h);
    ctx.closePath();
    ctx.fill();
    // Asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => ctx.fillRect(a.x, a.y, a.w, a.h));
    // Fuel cans
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => ctx.fillRect(f.x, f.y, f.w, f.h));
    // Fuel bar
    ctx.fillStyle = '#fff';
    ctx.fillRect(10, 10, 100, 10);
    ctx.fillStyle = '#0ff';
    ctx.fillRect(10, 10, fuel, 10);
    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px Arial';
    ctx.fillText('Score: ' + score, width - 100, 20);
    // Game over
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '48px Arial';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  };

  const loop = () => {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  };
  loop();
})();
